catalog_script_client.script:
function onLoad() {

	var ga_config = new GlideAjax('XalientGlideAjaxHelper');
	ga_config.addParam('sysparm_name','clientFormConfig');
	ga_config.addParam('sysparm_cat_item', getParameterValue('sys_id'));

	ga_config.getXMLAnswer(function (response) {
		var config_response = JSON.parse(response);
		var apps = config_response.business_applications.split(',');
		if (apps.length == 1) {
			g_form.setDisplay('application_filter','false');
		}
		if(config_response.access_item_picker == 'single'){
			g_form.setDisplay('isc_access_item_lc',false);
			g_form.setMandatory('isc_access_item',true);
		}
		if(config_response.access_item_picker == 'multiple'){
			g_form.setDisplay('isc_access_item',false);
			g_form.setMandatory('isc_access_item_lc',true);
		}

	});

	function getParameterValue(name) {
		var url = top.location.href;
		var value = new URLSearchParams(url).get(name);
		if (value) {
			return value;
		}
		if (!value) {
			try {
				var gUrl = new GlideURL();
				gUrl.setFromCurrent();
				value = gUrl.getParam(name);
				if (typeof value == 'undefined') {
					return '';
				} else {
					return value;
				}
			} catch (e) { }
		}
	}

}
